package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class CpioArchiveInputStream_skip_TriageGen2Test {

    /**
     * Helper to create a minimal valid CPIO stream for testing.
     * CPIO format varies, but for skip() we primarily care about the raw bytes being read.
     */
    private CpioArchiveInputStream createStream(byte[] data) throws IOException {
        return new CpioArchiveInputStream(new ByteArrayInputStream(data));
    }

    @Test
    public void testSkip_NegativeN() throws IOException {
        CpioArchiveInputStream input = createStream(new byte[10]);
        assertThrows(IllegalArgumentException.class, () -> {
            input.skip(-1L);
        });
        input.close();
    }

    @Test
    public void testSkip_ZeroN() throws IOException {
        byte[] data = new byte[]{1, 2, 3, 4, 5};
        CpioArchiveInputStream input = createStream(data);
        long skipped = input.skip(0L);
        assertEquals(0L, skipped);
        input.close();
    }

    @Test
    public void testSkip_NormalAmount() throws IOException {
        // We use a large enough array to ensure the loop runs multiple times 
        // depending on tmpbuf size (usually small in these implementations).
        byte[] data = new byte[100];
        for (int i = 0; i < 100; i++) {
            data[i] = (byte) i;
        }
        CpioArchiveInputStream input = createStream(data);

        // Skip 50 bytes
        long skipped = input.skip(50L);
        assertEquals(50L, skipped);

        // Verify next read is at index 50
        byte[] buffer = new byte[1];
        input.read(buffer, 0, 1);
        assertEquals((byte) 50, buffer[0]);

        input.close();
    }

    @Test
    public void testSkip_ExceedingAvailable() throws IOException {
        byte[] data = new byte[10];
        CpioArchiveInputStream input = createStream(data);

        // Try to skip 20 bytes when only 10 exist
        long skipped = input.skip(20L);
        assertEquals(10L, skipped);

        // Verify entryEOF is set (internal state check via behavior)
        // The next read should return -1
        byte[] buffer = new byte[1];
        int read = input.read(buffer, 0, 1);
        assertEquals(-1, read);

        input.close();
    }

    @Test
    public void testSkip_LargeN_IntegerOverflowProtection() throws IOException {
        // n is larger than Integer.MAX_VALUE to trigger Math.min(n, Integer.MAX_VALUE)
        long largeN = (long) Integer.MAX_VALUE + 100L;
        byte[] data = new byte[Integer.MAX_VALUE / 2]; // Sufficient size
        CpioArchiveInputStream input = createStream(data);

        // We don't want to actually allocate Integer.MAX_VALUE in a unit test if possible,
        // but to test the branch 'int max = (int) Math.min(n, Integer.MAX_VALUE)', 
        // we need n to be large.
        // However, the loop will stop at the end of the stream.

        long skipped = input.skip(largeN);
        // It should skip at most the size of the data provided
        assertEquals((long) data.length, skipped);
        input.close();
    }

    @Test
    public void testSkip_ExactlyMaxInt() throws IOException {
        // Test boundary where n == Integer.MAX_VALUE
        long n = Integer.MAX_VALUE;
        byte[] data = new byte[10];
        CpioArchiveInputStream input = createStream(data);

        long skipped = input.skip(n);
        assertEquals(10L, skipped);
        input.close();
    }

    @Test
    public void testSkip_AfterClose() throws IOException {
        CpioArchiveInputStream input = createStream(new byte[10]);
        input.close();
        // ensureOpen() should throw IOException if closed
        assertThrows(IOException.class, () -> {
            input.skip(1L);
        });
    }

    @Test
    public void testSkip_SmallBufferChunking() throws IOException {
        // This test ensures the 'if (len > this.tmpbuf.length)' branch is covered.
        // Since tmpbuf is private, we rely on the fact that skipping a large 
        // number of bytes will eventually trigger the len = tmpbuf.length logic.
        byte[] data = new byte[1000];
        CpioArchiveInputStream input = createStream(data);

        long skipped = input.skip(500L);
        assertEquals(500L, skipped);
        input.close();
    }
}
